using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train and save model at startup
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
TrainModel(modelPath);

// Register pooled prediction engine (thread-safe)
builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/predict", (CustomerInput input, PredictionEnginePool<CustomerInput, ChurnPrediction> pool) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability
    });
});

app.Run();

static void TrainModel(string modelPath)
{
    var mlContext = new MLContext(seed: 42);

    var dataPath = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "Data", "customers.csv");
    if (!File.Exists(dataPath))
        dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "customers.csv");

    var data = mlContext.Data.LoadFromTextFile<CustomerInput>(
        dataPath, hasHeader: true, separatorChar: ',');

    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

    var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerInput.Region))
        .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerInput.Age)))
        .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerInput.Income)))
        .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerInput.PurchaseHistory)))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(CustomerInput.Age), nameof(CustomerInput.Income),
            "RegionEncoded", nameof(CustomerInput.PurchaseHistory)))
        .Append(mlContext.Transforms.CopyColumns("Label", nameof(CustomerInput.Churned)))
        .Append(mlContext.BinaryClassification.Trainers.FastTree());

    var model = pipeline.Fit(split.TrainSet);

    // Evaluate
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions);
    Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");

    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");
}

public class CustomerInput
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4), ColumnName("Churned")]
    public bool Churned { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }
}

